mapper.select:
SELECT p.id AS product_id, p.name AS product_name, p.category_id, c.name AS category_name, p.specification, u.name AS unit_name, IFNULL(i.current_stock, 0) AS current_stock, p.safety_stock, IFNULL(i.frozen_stock, 0) AS frozen_stock, CASE WHEN p.safety_stock > 0 AND IFNULL(i.current_stock, 0) < p.safety_stock THEN true ELSE false END AS is_warning, (IFNULL(i.current_stock, 0) - p.safety_stock) AS difference, (IFNULL(i.current_stock, 0) * p.purchase_price) AS stock_value FROM product p LEFT JOIN product_category c ON p.category_id = c.id LEFT JOIN unit u ON p.unit_id = u.id LEFT JOIN inventory i ON p.id = i.product_id WHERE p.status = 1
AND p.name LIKE CONCAT('%', #{productName}, '%')
AND p.category_id = #{categoryId}
AND p.safety_stock > 0 AND IFNULL(i.current_stock, 0) < p.safety_stock
ORDER BY is_warning DESC, p.category_id, p.id LIMIT #{offset}, #{pageSize}

SELECT p.id AS product_id, p.name AS product_name, p.category_id, c.name AS category_name, p.specification, u.name AS unit_name, IFNULL(i.current_stock, 0) AS current_stock, p.safety_stock, IFNULL(i.frozen_stock, 0) AS frozen_stock, true AS is_warning, (IFNULL(i.current_stock, 0) - p.safety_stock) AS difference, (IFNULL(i.current_stock, 0) * p.purchase_price) AS stock_value FROM product p LEFT JOIN product_category c ON p.category_id = c.id LEFT JOIN unit u ON p.unit_id = u.id LEFT JOIN inventory i ON p.id = i.product_id WHERE p.status = 1 AND p.safety_stock > 0 AND IFNULL(i.current_stock, 0) < p.safety_stock
AND p.category_id = #{categoryId}
ORDER BY difference ASC
